// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor, uint256 warpTo) public {
        vm.assume(actor != address(c) && actor != address(0));
        amount = bound(amount, 1 ether, 10 ether);
        warpTo = bound(warpTo, block.timestamp + 1, block.timestamp + 365 days);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(warpTo);
        // attempt to withdraw the entire balance BEFORE the unlock time
        vm.prank(actor);
        c.Collect(amount);
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount, "funds locked until unlockTime must survive an early Collect");
    }
}
